interface LogEntry {
	key: number;
	ts: number;
	icon: string;
	msg: string;
	sub?: string;
}

let _logSeq = 0;

function makeEntry(icon: string, msg: string, sub?: string): LogEntry {
	return { key: _logSeq++, ts: Date.now(), icon, msg, sub };
}

